const modal=document.getElementById('modal');
let openIdx=null;
function renderMember(){
 if(openIdx===null)return;const t=team[openIdx],tx=i18n[lang];
 const photo=t.img?`<div class="modal-photo"><img src="${t.img}" alt="${t.n}"></div>`:`<div class="modal-photo initial">${t.n[0]}</div>`;
 document.getElementById('mBody').innerHTML=`${photo}<h3>${t.n}</h3><small>${tx[t.r]}</small><h4>${tx.mDesc}</h4><p>${t.d[lang]}</p><h4>${tx.mPart}</h4><p>${t.p[lang]}</p><h4>${tx.mFun}</h4><p>${t.f[lang]}</p>`}
function openMember(i){openIdx=i;renderMember();modal.classList.add('open')}
function closeModal(){modal.classList.remove('open');openIdx=null}
if(modal){modal.addEventListener('click',e=>{if(e.target===modal||e.target.classList.contains('close'))closeModal()});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()})}

