/* ===== HOME ONLY: interactive hero + industrial background ===== */
(function(){
 const hero=document.querySelector('.hero-img');if(!hero)return;
 const still=matchMedia('(prefers-reduced-motion:reduce)').matches;
 /* interactive hero: drifting nodes that link up and react to the pointer */
 const cv=document.createElement('canvas');cv.className='hero-canvas';hero.prepend(cv);
 const cx=cv.getContext('2d');let W,H,pts=[],m={x:-999,y:-999};
 function size(){W=cv.width=hero.clientWidth;H=cv.height=hero.clientHeight;
  const n=Math.max(24,Math.min(70,Math.round(W*H/16000)));
  pts=Array.from({length:n},()=>({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.35,vy:(Math.random()-.5)*.35,r:Math.random()<.15?3:1.8,c:['#ffffff','#ffffff','#ff8f8d','#6fe0a6'][Math.floor(Math.random()*4)]}))}
 function frame(){cx.clearRect(0,0,W,H);
  for(const p of pts){
   const dx=p.x-m.x,dy=p.y-m.y,d=Math.hypot(dx,dy);
   if(d<110&&d>0){p.vx+=dx/d*.05;p.vy+=dy/d*.05}
   p.vx*=.99;p.vy*=.99;
   if(Math.abs(p.vx)<.08)p.vx+=(Math.random()-.5)*.02;if(Math.abs(p.vy)<.08)p.vy+=(Math.random()-.5)*.02;
   p.x+=p.vx;p.y+=p.vy;
   if(p.x<0||p.x>W)p.vx*=-1;if(p.y<0||p.y>H)p.vy*=-1}
  for(let i=0;i<pts.length;i++){const a=pts[i];
   for(let j=i+1;j<pts.length;j++){const b=pts[j],d=Math.hypot(a.x-b.x,a.y-b.y);
    if(d<120){cx.strokeStyle='rgba(255,255,255,'+(.22*(1-d/120))+')';cx.lineWidth=1;cx.beginPath();cx.moveTo(a.x,a.y);cx.lineTo(b.x,b.y);cx.stroke()}}
   const dm=Math.hypot(a.x-m.x,a.y-m.y);
   if(dm<150){cx.strokeStyle='rgba(255,255,255,'+(.55*(1-dm/150))+')';cx.beginPath();cx.moveTo(a.x,a.y);cx.lineTo(m.x,m.y);cx.stroke()}
   cx.fillStyle=a.c;cx.globalAlpha=.8;cx.beginPath();cx.arc(a.x,a.y,a.r,0,7);cx.fill();cx.globalAlpha=1}
  if(!still)requestAnimationFrame(frame)}
 hero.addEventListener('pointermove',e=>{const r=hero.getBoundingClientRect();m.x=e.clientX-r.left;m.y=e.clientY-r.top});
 hero.addEventListener('pointerleave',()=>{m.x=m.y=-999});
 hero.addEventListener('click',e=>{const r=hero.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;
  pts.forEach(p=>{const dx=p.x-x,dy=p.y-y,d=Math.hypot(dx,dy)||1;if(d<220){p.vx+=dx/d*2.2;p.vy+=dy/d*2.2}})});
 addEventListener('resize',size);size();frame();
 /* industrial engineering background: gears, process flow, Pareto bars, conveyor */
 function gear(cx0,cy0,r,t,cls){let d='';const a=Math.PI*2/t;
  for(let i=0;i<t;i++){const s=i*a;
   [[s,r],[s+a*.2,r*1.18],[s+a*.5,r*1.18],[s+a*.7,r]].forEach(([ang,rad],k)=>{d+=(i===0&&k===0?'M':'L')+(cx0+Math.cos(ang)*rad).toFixed(1)+' '+(cy0+Math.sin(ang)*rad).toFixed(1)})}
  return `<g class="gear ${cls}"><path d="${d}Z"/><circle cx="${cx0}" cy="${cy0}" r="${r*.35}"/></g>`}
 document.body.insertAdjacentHTML('afterbegin',`<svg class="bg-deco bg-ind" viewBox="0 0 1200 800" preserveAspectRatio="xMidYMid slice" aria-hidden="true">
  ${gear(1080,120,38,12,'')}${gear(1146,172,24,8,'rev')}${gear(90,640,44,14,'slow')}${gear(166,700,26,9,'rev slow')}
  <g class="flow"><rect x="330" y="640" width="90" height="38" rx="6"/><path d="M420 659H470"/><path d="M500 640 530 659 500 678 470 659Z"/><path d="M530 659H580"/><rect x="580" y="640" width="90" height="38" rx="6"/><path class="path r" d="M500 678V716H625V678"/></g>
  <g class="bars"><path d="M820 330V250H1000"/><rect class="bar" x="835" y="290" width="22" height="40"/><rect class="bar b2" x="867" y="268" width="22" height="62"/><rect class="bar b3" x="899" y="300" width="22" height="30"/><rect class="bar b4" x="931" y="315" width="22" height="15"/><path class="path g" d="M835 282C880 262 920 290 975 270"/></g>
  <g class="belt"><rect x="60" y="300" width="300" height="14" rx="7"/><circle cx="67" cy="307" r="10"/><circle cx="353" cy="307" r="10"/><rect class="box" x="90" y="276" width="22" height="22"/><rect class="box b2" x="90" y="280" width="18" height="18"/></g>
 </svg>`);
})();
